#!/usr/bin/env node
// Generates web/src/py/solve-source.generated.ts from web/src/py/solve.py: a plain string
// constant, so that esbuild's bundle of src/mount.ts (package.json's "build" script) carries
// solve.py's source INSIDE the JS it ships, rather than the widget fetching a second file over
// the network at boot time -- a second round trip for a 4 KB Python file is a failure mode with
// no upside (runtime.ts's own import of SOLVE_PY_SOURCE points back here for the reasoning).
//
// The generated file is NOT committed (.gitignore) and is regenerated by both `npm run build`
// and `npm run check` before either does anything else -- the same shape test.sh's own first
// line ("npm run build") already uses to make docs/js/widgets.js fresh for every test run rather
// than committed and possibly stale (see that script's header comment). Regenerating it here
// means solve.py and the string TypeScript sees of it can never drift apart: there is exactly one
// artifact that could go stale (solve.py itself), not two.
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const solvePyPath = fileURLToPath(new URL("../src/py/solve.py", import.meta.url));
const outPath = fileURLToPath(new URL("../src/py/solve-source.generated.ts", import.meta.url));
const source = readFileSync(solvePyPath, "utf8");

// JSON.stringify, not a template literal: solve.py has no backtick or `${` today, but a template
// literal would need re-auditing every time solve.py's text changes to confirm neither ever
// appears in a docstring or string literal there. JSON.stringify escapes whatever the file
// contains -- quotes, backslashes, newlines -- into a valid JS/TS double-quoted string literal
// unconditionally, so this generator never has to reason about solve.py's own content.
const contents =
  `// GENERATED by web/scripts/gen-solve-source.mjs from web/src/py/solve.py -- do not edit.\n`
  + `// Not committed (.gitignore): regenerated by \`npm run build\` and \`npm run check\`.\n`
  + `export const SOLVE_PY_SOURCE: string = ${JSON.stringify(source)};\n`;

writeFileSync(outPath, contents);
